import type { AuctionState } from "./store";

export function isLocked(state: AuctionState): boolean {
  if (!state.lock?.unlockAt) {
    return false;
  }
  return new Date(state.lock.unlockAt).getTime() > Date.now();
}

export function lockPriceFromAmount(currentHigh: number): number {
  return Math.max(currentHigh * 3, currentHigh + 25);
}

export function lockPrice(state: AuctionState): number {
  const high = Math.max(state.currentBid, state.winner?.amount ?? 0);
  return lockPriceFromAmount(high);
}

export function msUntilUnlock(state: AuctionState): number {
  if (!state.lock?.unlockAt) {
    return 0;
  }
  return Math.max(0, new Date(state.lock.unlockAt).getTime() - Date.now());
}

import type { AuctionState } from "./store";

const DEFAULT_REPO = "sharadvc/tabtax";
const AUCTION_PATH = "data/auction.json";
const BRANCH = "main";

export function getGithubToken(): string | undefined {
  return process.env.TABTAX_GITHUB_TOKEN || process.env.GITHUB_TOKEN;
}

export function isPersistenceEnabled(): boolean {
  return Boolean(getGithubToken());
}

function getRepo(): string {
  return process.env.GITHUB_REPO || DEFAULT_REPO;
}

function emptyState(): AuctionState {
  return {
    version: 0,
    currentBid: 0,
    winner: null,
    lock: null,
    founders: [],
    history: [],
  };
}

type GithubContent = {
  sha: string;
  content: string;
};

async function fetchAuctionFile(): Promise<{
  state: AuctionState | null;
  sha: string | null;
}> {
  const token = getGithubToken();
  if (!token) {
    return { state: null, sha: null };
  }

  const [owner, repo] = getRepo().split("/");
  const url = `https://api.github.com/repos/${owner}/${repo}/contents/${AUCTION_PATH}?ref=${BRANCH}`;

  const res = await fetch(url, {
    headers: {
      Accept: "application/vnd.github+json",
      Authorization: `Bearer ${token}`,
      "X-GitHub-Api-Version": "2022-11-28",
    },
    cache: "no-store",
  });

  if (res.status === 404) {
    return { state: emptyState(), sha: null };
  }

  if (!res.ok) {
    console.error("GitHub read failed", res.status, await res.text());
    return { state: null, sha: null };
  }

  const data = (await res.json()) as GithubContent;
  const raw = Buffer.from(data.content.replace(/\n/g, ""), "base64").toString("utf8");
  const state = JSON.parse(raw) as AuctionState;
  return { state, sha: data.sha };
}

async function loadFromRawGithub(): Promise<AuctionState | null> {
  const [owner, repo] = getRepo().split("/");
  const url = `https://raw.githubusercontent.com/${owner}/${repo}/${BRANCH}/${AUCTION_PATH}`;
  try {
    const res = await fetch(url, { cache: "no-store" });
    if (!res.ok) {
      return null;
    }
    return (await res.json()) as AuctionState;
  } catch {
    return null;
  }
}

export async function loadPersistedState(): Promise<AuctionState | null> {
  if (getGithubToken()) {
    const result = await fetchAuctionFile();
    return result.state;
  }
  return loadFromRawGithub();
}

export async function savePersistedState(
  state: AuctionState,
  expectedSha: string | null
): Promise<boolean> {
  const token = getGithubToken();
  if (!token) {
    return false;
  }

  const [owner, repo] = getRepo().split("/");
  const url = `https://api.github.com/repos/${owner}/${repo}/contents/${AUCTION_PATH}`;

  const content = Buffer.from(JSON.stringify(state, null, 2), "utf8").toString("base64");

  const body: Record<string, string> = {
    message: "chore: update auction state",
    content,
    branch: BRANCH,
  };
  if (expectedSha) {
    body.sha = expectedSha;
  }

  const res = await fetch(url, {
    method: "PUT",
    headers: {
      Accept: "application/vnd.github+json",
      Authorization: `Bearer ${token}`,
      "X-GitHub-Api-Version": "2022-11-28",
      "Content-Type": "application/json",
    },
    body: JSON.stringify(body),
  });

  if (res.status === 409) {
    return false;
  }

  if (!res.ok) {
    console.error("GitHub write failed", res.status, await res.text());
    return false;
  }

  return true;
}

export async function readForUpdate(): Promise<{
  state: AuctionState;
  sha: string | null;
} | null> {
  const token = getGithubToken();
  if (!token) {
    return null;
  }
  const result = await fetchAuctionFile();
  if (!result.state) {
    return null;
  }
  return { state: result.state, sha: result.sha };
}

const buckets = new Map<string, { count: number; resetAt: number }>();

const WINDOW_MS = 60_000;
const MAX_REQUESTS = 12;

function hashIp(req: Request): string {
  const forwarded = req.headers.get("x-forwarded-for");
  const ip = forwarded?.split(",")[0]?.trim() || req.headers.get("x-real-ip") || "unknown";
  return ip;
}

export function rateLimitBid(req: Request): { ok: true } | { ok: false; retryAfter: number } {
  const key = hashIp(req);
  const now = Date.now();
  const entry = buckets.get(key);

  if (!entry || now >= entry.resetAt) {
    buckets.set(key, { count: 1, resetAt: now + WINDOW_MS });
    return { ok: true };
  }

  if (entry.count >= MAX_REQUESTS) {
    return { ok: false, retryAfter: Math.ceil((entry.resetAt - now) / 1000) };
  }

  entry.count += 1;
  return { ok: true };
}

export function siteUrlClient(): string {
  if (typeof window !== "undefined" && window.location.origin) {
